const config = $input.first().json;
const sinceDate = new Date();
sinceDate.setDate(sinceDate.getDate() - config.LOOKBACK_DAYS);

return [{
  json: {
    ...config,
    since_iso: sinceDate.toISOString(),
    since_date: sinceDate.toISOString().split('T')[0]
  }
}];

const cfg = $('Compute Date Window').first().json;
const sinceDate = new Date(cfg.since_iso);

// 1. Process Commits
let rawCommits = [];
try {
  rawCommits = $('GitHub - Fetch Commits').all().map(i => i.json);
} catch(e) {}
const commits = rawCommits
  .filter(c => c && c.commit && new Date(c.commit.author?.date || 0) >= sinceDate)
  .map(c => ({
    sha: c.sha ? c.sha.substring(0, 7) : '',
    author: c.commit?.author?.name || 'Unknown',
    message: (c.commit?.message || '').split('\n')[0]
  }));

// 2. Process Pull Requests (Merged only)
let rawPRs = [];
try {
  rawPRs = $('GitHub - Fetch Pull Requests').all().map(i => i.json);
} catch(e) {}
const mergedPRs = rawPRs
  .filter(pr => pr && pr.merged_at && new Date(pr.merged_at) >= sinceDate)
  .map(pr => ({
    number: pr.number,
    title: pr.title,
    author: pr.user?.login || 'unknown',
    merged_at: pr.merged_at
  }));

// 3. Process Closed Issues (excluding PRs)
let rawIssues = [];
try {
  rawIssues = $('GitHub - Fetch Issues').all().map(i => i.json);
} catch(e) {}
const closedIssues = rawIssues
  .filter(issue => issue && !issue.pull_request && issue.closed_at && new Date(issue.closed_at) >= sinceDate)
  .map(issue => ({
    number: issue.number,
    title: issue.title,
    closed_by: issue.closed_by?.login || 'unknown'
  }));

return [{
  json: {
    config: cfg,
    stats: {
      commits_count: commits.length,
      merged_prs_count: mergedPRs.length,
      closed_issues_count: closedIssues.length
    },
    activity_data: {
      commits,
      mergedPRs,
      closedIssues
    }
  }
}];

