const claudeResponse = $input.first().json;
const aggregateData = $('Aggregate GitHub Metrics').first().json;
const summaryText = claudeResponse.content?.[0]?.text || 'No summary generated.';
const config = aggregateData.config;

// Format message payload according to selected delivery channel
let payload = {};
if (config.DELIVERY_CHANNEL === 'DISCORD') {
  payload = {
    content: `📢 **Weekly Engineering Digest: ${config.GITHUB_OWNER}/${config.GITHUB_REPO}**\n\n${summaryText.substring(0, 1900)}`
  };
} else if (config.DELIVERY_CHANNEL === 'SLACK') {
  payload = {
    text: `*Weekly Engineering Digest: ${config.GITHUB_OWNER}/${config.GITHUB_REPO}*\n\n${summaryText}`
  };
} else {
  payload = {
    subject: `Weekly Dev Summary - ${config.GITHUB_OWNER}/${config.GITHUB_REPO}`,
    body: summaryText
  };
}

return [{
  json: {
    webhook_url: config.WEBHOOK_URL,
    channel: config.DELIVERY_CHANNEL,
    summary_markdown: summaryText,
    payload: payload
  }
}];
